142:func greedyShipWireDeltaChunks(packet ShipWireDeltaPacket) [][]map[string]any {
143:	updates := packet.ShipUpdates
144:	if len(updates) == 0 {
145:		return [][]map[string]any{{}}
146:	}
147:
148:	estimatedPacket := packet
149:	estimatedPacket.Metadata.ChunkCount = 2
150:	estimatedPacket.Metadata.IsFinalChunk = true
151:
152:	chunks := make([][]map[string]any, 0, len(updates))
153:	chunkStart := 0
154:	for idx := 0; idx < len(updates); idx++ {
155:		if idx > chunkStart {
156:			trialUpdates := updates[chunkStart : idx+1]
157:			if estimateShipDeltaPacketBytes(estimatedPacket, trialUpdates) > HardCapBytes {
158:				chunks = append(chunks, updates[chunkStart:idx])
159:				chunkStart = idx
160:			}
161:		}
162:	}
163:	chunks = append(chunks, updates[chunkStart:])
164:	return chunks
165:}
